const { seg, eo, lerp } = kit;

kit.scene('rail-swap', {
  init(kit) {
    const markUrl = W.logoMarkUrl(kit);
    kit.stage.append(kit.h(
      '<div class="ground">' +
      W.studyChrome('2 · Collapsed Rail Logo-to-Icon Swap', 'Zero layout shift', 'Same-center 44x44 hit target · Issue #11') +
      '<div class="ui-window" style="left:160px;top:164px;width:940px;height:740px;display:flex">' +
        '<aside style="width:64px;flex-shrink:0;height:100%;box-sizing:border-box;background:var(--nav-bg);padding:16px 10px;display:flex;flex-direction:column;align-items:center;gap:18px;position:relative">' +
          '<div style="position:relative;width:44px;height:44px;display:flex;align-items:center;justify-content:center">' +
            '<div class="rail-swap-btn" style="width:44px;height:44px;border-radius:6px;display:flex;align-items:center;justify-content:center;color:var(--main);position:relative;box-sizing:border-box">' +
              '<img class="rail-swap-mark" src="' + markUrl + '" alt="Exam App mark" style="position:absolute;width:24px;height:24px"/>' +
              '<span class="rail-swap-glyph" style="position:absolute;display:flex;opacity:0">' + W.panelSvg() + '</span>' +
            '</div>' +
            '<div class="rail-swap-ring" style="position:absolute;inset:-5px;border:2px solid var(--accent);border-radius:10px;opacity:0;pointer-events:none"></div>' +
            '<div class="rail-swap-tip" style="position:absolute;left:58px;top:4px;white-space:nowrap;background:var(--main);color:var(--ground);padding:8px 14px;border-radius:6px;font-size:16px;font-weight:600;opacity:0">Expand sidebar</div>' +
          '</div>' +
          '<div style="display:flex;flex-direction:column;gap:8px;align-items:center">' +
            '<div style="width:48px;height:44px;border-radius:6px;background:var(--tint);color:var(--accent);display:flex;align-items:center;justify-content:center">' + W.docSvg() + '</div>' +
            '<div style="width:48px;height:44px;border-radius:6px;color:var(--second);display:flex;align-items:center;justify-content:center">' + W.docSvg() + '</div>' +
          '</div>' +
        '</aside>' +
        '<main style="flex:1;padding:36px 44px;display:flex;flex-direction:column;gap:18px">' +
          '<span style="font-size:15px;font-weight:600;color:var(--second)">DATAPREV · 2026 · Analyst</span>' +
          '<h2 style="margin:0;font-size:20px;font-weight:600;color:var(--main)">Question 1</h2>' +
          '<p style="margin:0;font-size:17px;line-height:26px;color:var(--main)">Which HTTP method is defined as safe and idempotent?</p>' +
          '<div style="padding:10px 12px;border-radius:6px;background:var(--tint);font-size:16px">B. GET</div>' +
          '<div style="padding:10px 12px;font-size:16px;color:var(--second)">C. PATCH</div>' +
        '</main>' +
      '</div>' +
      '<div style="position:absolute;left:1160px;top:164px;width:600px;display:flex;flex-direction:column;gap:20px">' +
        '<div class="rail-swap-card0" style="padding:22px 24px;border-radius:12px;background:var(--nav-bg);border:2px solid var(--accent)">' +
          '<div style="font-size:20px;font-weight:700;color:var(--main);margin-bottom:6px">1 · Rest state</div>' +
          '<div style="font-size:17px;line-height:24px;color:var(--second)">Shows only the compact Exam App mark centered in the 64px rail header.</div>' +
        '</div>' +
        '<div class="rail-swap-card1" style="padding:22px 24px;border-radius:12px;background:var(--nav-bg);border:2px solid transparent">' +
          '<div style="font-size:20px;font-weight:700;color:var(--main);margin-bottom:6px">2 · Pointer hover</div>' +
          '<div style="font-size:17px;line-height:24px;color:var(--second)">Swaps in-place at the exact center to the expand glyph and reveals the tooltip.</div>' +
        '</div>' +
        '<div class="rail-swap-card2" style="padding:22px 24px;border-radius:12px;background:var(--nav-bg);border:2px solid transparent">' +
          '<div style="font-size:20px;font-weight:700;color:var(--main);margin-bottom:6px">3 · Keyboard focus</div>' +
          '<div style="font-size:17px;line-height:24px;color:var(--second)">Adds a separated 2px focus outline while keeping the expand glyph and tooltip visible.</div>' +
        '</div>' +
        '<div style="padding:18px 22px;border-radius:12px;background:var(--tint);font-size:17px;line-height:24px;color:var(--main);font-weight:600">' +
          'Touch and no-hover devices display the expand glyph directly.' +
        '</div>' +
      '</div>' +
      '</div>'
    ));

    const q = (s) => kit.stage.querySelector(s);
    this.btn = q('.rail-swap-btn');
    this.mark = q('.rail-swap-mark');
    this.glyph = q('.rail-swap-glyph');
    this.ring = q('.rail-swap-ring');
    this.tip = q('.rail-swap-tip');
    this.c0 = q('.rail-swap-card0');
    this.c1 = q('.rail-swap-card1');
    this.c2 = q('.rail-swap-card2');

    this.cur = kit.cursor();
    this.cur.keys = [
      { t: 0.3, at: [420, 340] },
      { t: 1.05, at: [192, 202] },
      { t: 2.35, at: [420, 340] }
    ];
    this.cur.visible = (t) => seg(t, 0.15, 0.35) * (1 - seg(t, 2.35, 2.65));
  },
  render(t) {
    const hoverPhase = seg(t, 1.0, 1.25) * (1 - seg(t, 2.15, 2.35));
    const focusPhase = seg(t, 2.6, 2.85) * (1 - seg(t, 4.1, 4.4));
    const swapped = Math.max(hoverPhase, focusPhase);

    this.mark.style.opacity = 1 - swapped;
    this.glyph.style.opacity = swapped;
    this.btn.style.background = hoverPhase > 0.1 ? 'var(--hover-bg)' : 'transparent';
    this.ring.style.opacity = focusPhase;

    const tipIn = eo(swapped);
    this.tip.style.opacity = tipIn;
    this.tip.style.transform = 'translateX(' + lerp(-8, 0, tipIn).toFixed(1) + 'px)';

    const stage = focusPhase > 0.2 ? 2 : (hoverPhase > 0.2 ? 1 : 0);
    this.c0.style.borderColor = stage === 0 ? 'var(--accent)' : 'transparent';
    this.c1.style.borderColor = stage === 1 ? 'var(--accent)' : 'transparent';
    this.c2.style.borderColor = stage === 2 ? 'var(--accent)' : 'transparent';

    this.cur.render(t);
  }
});
